/* Which languages each blog post is published in, for the pages that cannot
   read the blog plugin: hreflang and the language switch (src/website/lang.js)
   and the sitemaps. From src/data/blog-intl/ (scripts/lib/vite-blog-split.mjs). */
import fs from 'node:fs';
import { POSTS } from '../src/data/blogData.js';
import { readIntl, postLangs } from './lib/vite-blog-split.mjs';

const intl = readIntl();
const map = Object.fromEntries(POSTS.map(p => [p.slug, postLangs(p.slug, intl)]));
fs.writeFileSync('src/website/blogLangs.js',
  '/* Generated by scripts/generate-blog-langs.mjs on every build. Do not edit. */\n'
  + `export const BLOG_LANGS = ${JSON.stringify(map, null, 1)};\n`);
const n = l => Object.values(map).filter(x => x.includes(l)).length;
console.log(`✅ blog languages: en ${n('en')}, de ${n('de')}, es ${n('es')}`);
